import React from 'react';

export default function Nav({ page, setPage }) {
  const links = [
    { id:'home',      label:'Hem' },
    { id:'checkin',   label:'Check-in' },
    { id:'history',   label:'Historik' },
    { id:'breathing', label:'Andning' },
  ];
  return (
    <nav style={{ position:'fixed', top:0, left:0, right:0, zIndex:100, display:'flex', alignItems:'center', justifyContent:'space-between', padding:'0 24px', height:56, background:'rgba(240,237,232,0.75)', backdropFilter:'blur(24px)', borderBottom:'1px solid rgba(0,0,0,0.07)' }}>
      <button onClick={()=>setPage('home')} style={{ display:'flex', alignItems:'center', gap:8, fontSize:15, fontWeight:700, letterSpacing:'-0.02em', color:'#1a1a1e' }}>
        <div style={{ width:26, height:26, borderRadius:8, background:'rgba(0,0,0,0.1)', border:'1px solid rgba(0,0,0,0.08)', display:'flex', alignItems:'center', justifyContent:'center', fontSize:13 }}>🌀</div>
        Spiral
      </button>
      <div style={{ display:'flex', gap:2, background:'rgba(0,0,0,0.06)', border:'1px solid rgba(0,0,0,0.06)', borderRadius:12, padding:3 }}>
        {links.map(l => (
          <button key={l.id} onClick={()=>setPage(l.id)} style={{ padding:'6px 14px', borderRadius:9, fontSize:12, fontWeight:500, color: page===l.id ? '#1a1a1e' : 'rgba(26,26,30,0.4)', background: page===l.id ? 'rgba(255,255,255,0.7)' : 'transparent', transition:'all .2s', border: page===l.id ? '1px solid rgba(0,0,0,0.08)' : '1px solid transparent' }}>
            {l.label}
          </button>
        ))}
      </div>
    </nav>
  );
}
